{-# LANGUAGE OverloadedStrings #-}
module Aihc.Capi (CapiWrapper(..), CapiValue(..), capiWrapperSymbol, moduleCapiWrappers, interfaceCapiWrappers, renderCapiStub, parseDependencyFile) where {
import Aihc.Resolve (PackageId(..));
import Aihc.Tc (CType(..), TcInterface, TcTermKey(..), tcInterfaceForeignImports);
import Aihc.Tc.Annotations (TcForeignAbiType(..), TcForeignCApi(..), TcForeignCApiKind(..), TcForeignImportAnnotation(..), TcForeignImportInfo(..), TcForeignMarshal(..));
import Data.Char (isAlphaNum, isAscii, ord);
import Data.List (nub, sortOn);
import Data.Text (Text);
import Data.Text qualified as T;
import Numeric (showHex);
capiWrapperSymbol :: TcTermKey -> Text;
capiWrapperSymbol key = case key of {
  TcTermGlobal (PackageId package) owner name -> T.intercalate "_" ("aihc_capi" : map escapeSymbolPart [package, owner, name]);
  TcTermLocal unique -> "aihc_capi_local_" <> T.pack (show unique)};
escapeSymbolPart :: Text -> Text;
escapeSymbolPart = T.concatMap escapeCharacter where {
  escapeCharacter character | isAscii character && isAlphaNum character = T.singleton character | character == '_' = "__" | character == '.' = "_d" | character == '-' = "_m" | otherwise = "_x" <> T.pack (showHex (ord character) "") <> "_"};
data CapiWrapper = CapiWrapper { capiWrapperName :: !Text, capiWrapperEntity :: !Text, capiWrapperCApi :: !TcForeignCApi, capiWrapperArguments :: ![CapiValue], capiWrapperResult :: !CapiValue } deriving (Eq, Show);
data CapiValue = CapiValue { capiValueAbiType :: !TcForeignAbiType, capiValueCType :: !(Maybe CType) } deriving (Eq, Show);
capiValue :: TcForeignMarshal -> CapiValue;
capiValue marshal = CapiValue {capiValueAbiType = tcForeignAbiType marshal, capiValueCType = tcForeignCType marshal};
moduleCapiWrappers :: Text -> TcInterface -> [CapiWrapper];
moduleCapiWrappers moduleName = interfaceCapiWrappersWhere (== moduleName);
interfaceCapiWrappers :: TcInterface -> [CapiWrapper];
interfaceCapiWrappers = interfaceCapiWrappersWhere (const True);
interfaceCapiWrappersWhere :: (Text -> Bool) -> TcInterface -> [CapiWrapper];
interfaceCapiWrappersWhere owned interface = sortOn capiWrapperName $ nub [CapiWrapper {capiWrapperName = capiWrapperSymbol key, capiWrapperEntity = tcForeignSymbol plan, capiWrapperCApi = capi, capiWrapperArguments = map capiValue (tcForeignArguments plan), capiWrapperResult = capiValue (tcForeignResult plan)} | (key@(TcTermGlobal _ owner _), TcForeignCCallImport _ plan) <- tcInterfaceForeignImports interface, owned owner, Just capi <- [tcForeignCApi plan]];
renderCapiStub :: Text -> [CapiWrapper] -> Maybe Text;
renderCapiStub _ [] = Nothing;
renderCapiStub moduleName wrappers = Just . T.unlines $ ["/* Generated by aihc for the capi foreign imports of " <> moduleName <> ". Do not edit. */", "#include \"HsFFI.h\"", ""] <> [includeDirective header | header <- headers] <> ["" | not (null headers)] <> map definition wrappers where {
  headers = nub $ [header | wrapper <- wrappers, value <- capiWrapperResult wrapper : capiWrapperArguments wrapper, Just spelled <- [capiValueCType value], Just header <- [cTypeHeader spelled]] <> [header | wrapper <- wrappers, Just header <- [tcForeignCApiHeader (capiWrapperCApi wrapper)]];
  includeDirective header = "#include \"" <> header <> "\"";
  definition wrapper = cType (capiWrapperResult wrapper) <> " " <> capiWrapperName wrapper <> "(" <> parameters wrapper <> ") { " <> body wrapper <> " }";
  parameters wrapper = case capiWrapperArguments wrapper of {
  [] -> "void";
  arguments -> T.intercalate ", " [cType argument <> " " <> argumentName index | (index, argument) <- zip [1 :: Int ..] arguments]};
  body wrapper = let {
  returned = case capiValueAbiType (capiWrapperResult wrapper) of {
  TcForeignVoid -> "";
  _ -> "return "}} in returned <> entity wrapper <> ";";
  entity wrapper = case tcForeignCApiKind (capiWrapperCApi wrapper) of {
  TcForeignCApiValue -> capiWrapperEntity wrapper;
  TcForeignCApiFunction -> capiWrapperEntity wrapper <> "(" <> T.intercalate ", " [argumentName index | index <- [1 .. length (capiWrapperArguments wrapper)]] <> ")"};
  argumentName index = "a" <> T.pack (show index)};
cType :: CapiValue -> Text;
cType value = case capiValueCType value of {
  Just spelled -> cTypeName spelled;
  Nothing -> abiCType (capiValueAbiType value)};
abiCType :: TcForeignAbiType -> Text;
abiCType abiType = case abiType of {
  TcForeignInt -> "HsInt";
  TcForeignInt8 -> "HsInt8";
  TcForeignInt16 -> "HsInt16";
  TcForeignInt32 -> "HsInt32";
  TcForeignInt64 -> "HsInt64";
  TcForeignWord -> "HsWord";
  TcForeignWord8 -> "HsWord8";
  TcForeignWord16 -> "HsWord16";
  TcForeignWord32 -> "HsWord32";
  TcForeignWord64 -> "HsWord64";
  TcForeignFloat -> "HsFloat";
  TcForeignDouble -> "HsDouble";
  TcForeignAddr -> "HsPtr";
  TcForeignVoid -> "void"};
parseDependencyFile :: String -> [FilePath];
parseDependencyFile = prerequisites . tokenize;
prerequisites :: [DependencyToken] -> [FilePath];
prerequisites tokens = case dropWhile (/= DependencyColon) tokens of {
  _ : rest -> [path | DependencyPath path <- rest];
  [] -> []};
data DependencyToken = DependencyColon | DependencyPath !FilePath deriving (Eq, Show);
tokenize :: String -> [DependencyToken];
tokenize text = case dropSeparators text of {
  [] -> [];
  ':' : rest -> DependencyColon : tokenize rest;
  rest -> let {
  (path, remaining) = readPath rest} in DependencyPath path : tokenize remaining} where {
  dropSeparators text' = case text' of {
  character : rest | isSeparator character -> dropSeparators rest;
  '\\' : '\n' : rest -> dropSeparators rest;
  _ -> text'};
  isSeparator character = character `elem` (" \t\r\n" :: String);
  readPath text' = case text' of {
  [] -> ("", "");
  '\\' : '\n' : rest -> ("", rest);
  '\\' : character : rest | character `elem` (" :\\#" :: String) -> consume character rest;
  '$' : '$' : rest -> consume '$' rest;
  ':' : rest -> ("", ':' : rest);
  character : rest | isSeparator character -> ("", rest) | otherwise -> consume character rest};
  consume character rest = let {
  (path, remaining) = readPath rest} in (character : path, remaining)}
}
